import{_ as a,H as s,f as n,i as t}from"./chunks/framework.BH2BK_3i.js";const T=JSON.parse('{"title":"16-服务器为什么回复HTTP400？","description":"","frontmatter":{},"headers":[{"level":2,"title":"HTTP 协议的前世今生","slug":"http-协议的前世今生","link":"#http-协议的前世今生","children":[]},{"level":2,"title":"案例：服务器为什么回复 HTTP 400？","slug":"案例-服务器为什么回复-http-400","link":"#案例-服务器为什么回复-http-400","children":[{"level":3,"title":"开始排查","slug":"开始排查","link":"#开始排查","children":[]},{"level":3,"title":"究竟什么是 HTTP 400？","slug":"究竟什么是-http-400","link":"#究竟什么是-http-400","children":[]},{"level":3,"title":"寻找突破口","slug":"寻找突破口","link":"#寻找突破口","children":[]},{"level":3,"title":"Authorization 头部","slug":"authorization-头部","link":"#authorization-头部","children":[]},{"level":3,"title":"HTTP 报文分隔","slug":"http-报文分隔","link":"#http-报文分隔","children":[]},{"level":3,"title":"定位不合规处","slug":"定位不合规处","link":"#定位不合规处","children":[]}]},{"level":2,"title":"实验","slug":"实验","link":"#实验","children":[{"level":3,"title":"实验 1：对 HTTP 发送不合规的请求","slug":"实验-1-对-http-发送不合规的请求","link":"#实验-1-对-http-发送不合规的请求","children":[]},{"level":3,"title":"实验 2：对 HTTPS 发送不合规的请求","slug":"实验-2-对-https-发送不合规的请求","link":"#实验-2-对-https-发送不合规的请求","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"网络排查案例课/16-服务器为什么回复HTTP400？.md","filePath":"网络排查案例课/16-服务器为什么回复HTTP400？.md","lastUpdated":1795563497000}'),i={name:"网络排查案例课/16-服务器为什么回复HTTP400？.md"};function p(l,e,o,E,h,c){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="_16-服务器为什么回复http400" tabindex="-1">16-服务器为什么回复HTTP400？ <a class="header-anchor" href="#_16-服务器为什么回复http400" aria-label="Permalink to &quot;16-服务器为什么回复HTTP400？&quot;">​</a></h1><p>你好，我是胜辉。</p><p>在上节课里，我们回顾了一个与 HTTP 协议相关的 Nginx 499 的案例。在应用层的众多“明星”里，HTTP 协议无疑是“顶流”了，可以说目前互联网上的大部分业务（电商、社交等），都是基于 HTTP 协议，当然也包括我们用极客时间学习的时候，也是在用 HTTP。那么相应的，HTTP 方面的排查能力，对于我们做开发和运维技术工作来说，就更加重要了。因为不少现实场景中的故障和难题，就与我们对 HTTP 的理解以及排查能力，有着密切的联系。</p><p>所以这一讲，我们会来看一个 HTTP 相关的报错案例，深入学习这其中的排查技巧。同时，我也会带你学习 HTTP 这个重要协议的规范部分。这样，以后你处理类似的像 HTTP 4xx、5xx的报错，或者其他跟 HTTP 协议本身相关的问题时，就有分寸，知道问题大概的方向在哪里、如何开展排查了。</p><p>那么在介绍案例之前，我们先简单地回顾一下 HTTP 协议。</p><h2 id="http-协议的前世今生" tabindex="-1">HTTP 协议的前世今生 <a class="header-anchor" href="#http-协议的前世今生" aria-label="Permalink to &quot;HTTP 协议的前世今生&quot;">​</a></h2><p>HTTP 的英文全称是 Hypertext Transfer Protocol，中文是超文本传输协议，它的奠基者是英国计算机科学家蒂姆·博纳斯·李（Tim Berners-Lee）。1990 年，他为了解决任职的欧洲核子研究组织（CERN）里，科学家们无法方便地分享文件和信息的问题，由此创造了 HTTP 协议。</p><p>实际上，在当时也有其他一些协议能实现信息共享的功能，比如 FTP、SMTP、NNTP 等，为什么还要另外创造 HTTP 呢？这是因为这些协议并不满足博纳斯·李的需求，比如：</p><ul><li><p>FTP 只是用来传输和获取文件，它无法方便地展示文本和图片；</p></li><li><p>NNTP 用来传输新闻，但不适合展示存档资料；</p></li><li><p>SMTP 是邮件传输协议，缺乏目录结构。</p></li></ul><p>而博纳斯·李需要的是“图形化的、只要点击一下就能进入到其他资料的系统”。鉴于以上协议无法实现，他就设计了 HTTP。也因为这个巨大的贡献，博纳斯·李获得了 2016 年的图灵奖，可以说是图灵奖的一次“回国”。</p><p>在 2015 年之前，HTTP 先后有 0.9、1.0、1.1 三个版本，其中 HTTP/1.0 和 1.1 合称HTTP/1.x。虽然谷歌在 2009 年就提出了 SPDY，但最终被接纳成为 HTTP/2，也已经是2015 年的事了。最近几年蓬勃发展的还有 HTTP/3（也就是 QUIC 上的 HTTP/2）。但从语义上说，HTTP/2 跟 HTTP/1.x 是保持一致的。HTTP/2 不同，主要是在传输过程中，在 TCP 和HTTP 之间，增加了一层传输方面的逻辑。</p><ul><li>补充：RFC7540定义了 HTTP/2 的协议规范，而 HTTP/1.1 在 1999 年 6 月的RFC2616里已经确定了大部分内容。</li></ul><p>什么叫做“语义上是一致的”呢？举个例子，在 HTTP/2 里面，header 和 body 的定义和规则，</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>就跟 HTTP/1.x 一样。比如 User-agent: curl/7.68.0 这样一个 header，在 HTTP/1.x</span></span></code></pre></div><p>里是代表了这次访问的客户端的名称和版本，而在 HTTP/2 里，依然是这个含义，没有任何变化。</p><p>从这一点上看，你甚至可以把 HTTP/2 理解为是在 HTTP/1.x 的语义的基础上，增加了一个介于 TCP 和 HTTP 之间的新的“传输层”。也就是下图这样：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/1.png" alt=""></a></p><p>目前最新的 HTTP/3 仍在讨论过程中，还未正式发布。它也依然保持了之前版本 HTTP 的语义，但在传输层上做了彻底的“革命”：把传输层协议从 TCP 换成了 UDP。根据 w3techs.com（一家网络技术调查网站）的数据，截至 2022 年 2 月 22 日，有 25.2% 的站点已经支持了HTTP/3。</p><p>好，回顾完 HTTP 的历史，我们已经比较清楚它的来龙去脉了。那么接下来要讲的案例，就会帮助我们拆解 HTTP 协议的一些细节，梳理对这种类型的问题的排查思路。</p><h2 id="案例-服务器为什么回复-http-400" tabindex="-1">案例：服务器为什么回复 HTTP 400？ <a class="header-anchor" href="#案例-服务器为什么回复-http-400" aria-label="Permalink to &quot;案例：服务器为什么回复 HTTP 400？&quot;">​</a></h2><p>这是前几年我在公有云服务时候的一个案例。当时一个客户测试我们的对象存储服务，这个服务是通过 HTTP 协议存放和读取文件的。它比较适合存放非结构化的数据，比如日志文件、图片文件等。因为依托于 HTTP 协议，浏览这种存储的方法很方便，比如用浏览器就可以直接访问。</p><p>但是，在客户的测试结果中报告大量 HTTP 400 的报错。我们也很意外，其他客户用的都挺好，为什么这个客户就不行呢？</p><h3 id="开始排查" tabindex="-1">开始排查 <a class="header-anchor" href="#开始排查" aria-label="Permalink to &quot;开始排查&quot;">​</a></h3><p>按照惯例，我们还是进行了抓包。这次是在客户端抓取的，我们看一下 Expert Information：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/2.png" alt=""></a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>其中，我们需要重点关注 HTTP 事务，也就是上图中的Chat HTTP/1.1 200 OK\\r\\n这部</span></span></code></pre></div><p>分，这里面都是 HTTP 事务的报文。由于第一个被 Wireshark 判定为 HTTP 事务的报文，是一个 HTTP 200 OK 的返回报文，所以就显示为这里的 Summary 栏的信息。</p><ul><li>补充：这里我修改过抓包，所以展现在 Expert Information 里面的样子，跟正常抓取完整报文的情况略有不同。比如这个示例文件里，第一个 HTTP 报文其实是 POST，那么Summary 栏显示的，应该是 POST 请求而不是 HTTP/1.1 200 OK。但是，这不影响排查和分析。</li></ul><p>既然这次是明确要排查 HTTP 400 报错，所以我们直接点开这些 HTTP 事务：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/3.png" alt=""></a></p><p>可见，这里有 200 OK 这样的正常响应，也有 400 Bad Request 这样的异常响应。</p><p>我们找一个请求，Follow TCP Stream 来看一下详细情况。比如，我们选中 23 号报文，此时主界面也自动跳转到了这个报文的位置。我们选中它，右单击后选择 Follow -&gt; TCP Stream：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/4.png" alt=""></a></p><p>我们来看一下整个 TCP 流：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/5.png" alt=""></a></p><p>在 Wireshark 里，HTTP 请求是红色字体，而 HTTP 响应是蓝色字体。显然，紧随在请求之后就是响应了，而蓝色字的第一行就是 HTTP/1.1 400 Bad Request。这就是我们要排查的问题。</p><p>然后我们需要搞清楚问题的定义了：HTTP 400 到底是什么？</p><h3 id="究竟什么是-http-400" tabindex="-1">究竟什么是 HTTP 400？ <a class="header-anchor" href="#究竟什么是-http-400" aria-label="Permalink to &quot;究竟什么是 HTTP 400？&quot;">​</a></h3><p>要回答这个问题，最准确的办法，还是阅读 RFC，看看标准里面到底怎么说。HTTP 的 RFC有过好几版，1999 年 6 月的RFC2616确定了 HTTP 的大部分规范，而后在7230、7231、7232等 RFC 中做了更新和细化。RFC2616 是这样定义 400 Bad Request 的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>400 Bad Request</span></span>
<span class="line"><span>  The request could not be understood by the server due to malformed</span></span>
<span class="line"><span>  syntax. The client SHOULD NOT repeat the request without</span></span>
<span class="line"><span>  modifications.</span></span></code></pre></div><p>也就是：这个请求因为语法错误而无法被服务端理解。客户端不可以不做修改就重复同样的请求。</p><p>此外，RFC2616 里还定义了几种必须返回 400 的情况，比如：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A client MUST include a Host header field in all HTTP/1.1 request</span></span>
<span class="line"><span>  messages . If the requested URI does not include an Internet host</span></span>
<span class="line"><span>  name for the service being requested, then the Host header field MUST</span></span>
<span class="line"><span>  be given with an empty value. An HTTP/1.1 proxy MUST ensure that any</span></span>
<span class="line"><span>  request message it forwards does contain an appropriate Host header</span></span>
<span class="line"><span>  field that identifies the service being requested by the proxy. All</span></span>
<span class="line"><span>  Internet-based HTTP/1.1 servers MUST respond with a 400 (Bad Request)</span></span>
<span class="line"><span>  status code to any HTTP/1.1 request message which lacks a Host header</span></span>
<span class="line"><span>  field.</span></span></code></pre></div><p>其他还有好几种情况，就不一一罗列了。</p><p>那么显然，400 Bad Request 的语义，就是让服务端告诉客户端：你发过来的请求不合规，我无法理解，所以我用 400 来告诉你这一点。</p><p>但是，我们也不可能去穷举所有可能出现的不合规类型。那么在这个案例里面，究竟是哪里出了问题呢？</p><h3 id="寻找突破口" tabindex="-1">寻找突破口 <a class="header-anchor" href="#寻找突破口" aria-label="Permalink to &quot;寻找突破口&quot;">​</a></h3><p>有时候，我们做排查工作，需要一点灵感，也需要一点耐心。对着这个页面，如果你对 HTTP协议并不是很熟悉，那么很难直接用肉眼就“看出”问题来。</p><p>那我们来玩个游戏怎么样：“大家来找茬”。你应该已经明白我的意思了，我们要做的是：对比分析。我们只需要把一个正常和一个异常的响应报文放在一起比较，也许就能找到原因了。</p><p>正巧，这次客户做的测试里，也有成功的请求。比如这个抓包文件里的 HTTP 200 OK。那么，我们就借助这样的一个 200 OK 的 TCP 流，来对比分析下。</p><p>说到这里，你可能已经想起我们在第 5 讲的时候，也用过这种对比分析的方法。当时是排查一个乱序引起应用层故障的问题，我们对比了客户端抓包文件和服务端抓包文件这两个文件，而它们代表的是同一个 TCP 流，我们也因此找到了问题的关键，也就是防火墙引发了报文乱序的现象。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/6.png" alt=""></a></p><p>当前的案例跟第 5 讲的案例就有所不同了，这次比较的是同一个抓包文件里的两个不同的TCP 流，也可以说是两个不同的应用层事务。这两个事务，一个成功，一个失败。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/7.png" alt=""></a></p><p>我们还是需要一个大一点的显示屏，把 HTTP 200 的报文找到后，Follow TCP Stream，随后的弹窗里就展示了这次成功的应用层消息的细节；然后选取 HTTP 400 的报文，也同样做一遍。然后我们把两个窗口挪到齐平的位置。</p><p>好，我们的对比开始了：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/8.png" alt=""></a></p><p>你能找到几个“茬”呢？因为这是两次不同的事务，所以请求和回复的字符肯定也十分不同，所以我们应该集中在格式上，而不是字符。</p><p>你可能首先注意到了两次的 HTTP 方法不同：左边是 PUT，右边是 POST。</p><p>这是否说明，问题就是服务端不支持 PUT 方法导致了 HTTP 400 呢？这个很容易排除。因为，如果真的是服务端对 PUT 的处理有问题，那么其他客户还怎么使用 PUT 呢？所以，即使这个问题跟 PUT 还是有点关系的话，我们也要转换一下问题描述，变成：为什么这个客户端发送的 PUT 请求会引起 HTTP 400？</p><p>然后，你可能会发现，左边的 PUT 请求里有 Authorization 头部，而右边 POST 请求里没有这个头部。</p><p>左边这个 Authorization 请求的头部格式是这样的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一开始是 PUT /123456 HTTP/1.1，然后换行；</span></span>
<span class="line"><span>接着是 Authorization: UCloud 这样一个头部，然后换行；</span></span>
<span class="line"><span>然后是 abc@def.com:blahblah 这种形式，看起来是一个邮箱地址后接冒号，然后是一</span></span></code></pre></div><ul><li>串编码过的字符串。</li></ul><p>你是不是觉得这部分的格式有点问题？这其实也是一个知识点了：HTTP Authorization 头部的格式。</p><h3 id="authorization-头部" tabindex="-1">Authorization 头部 <a class="header-anchor" href="#authorization-头部" aria-label="Permalink to &quot;Authorization 头部&quot;">​</a></h3><p>我们看看RFC2616里，对 Authorization 头部是怎么规定的：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>14.8 Authorization</span></span>
<span class="line"><span>     A user agent that wishes to authenticate itself with a server--</span></span>
<span class="line"><span>     usually, but not necessarily, after receiving a 401 response--does</span></span>
<span class="line"><span>     so by including an Authorization request-header field with the</span></span>
<span class="line"><span>     request.  The Authorization field value consists of credentials</span></span>
<span class="line"><span>     containing the authentication information of the user agent for</span></span>
<span class="line"><span>     the realm of the resource being requested.</span></span>
<span class="line"><span>         Authorization  = &quot;Authorization&quot; &quot;:&quot; credentials</span></span>
<span class="line"><span>简单来说，它也跟其他的 HTTP 头部的规定一样，也是 key:value 的形式。语法格式是这</span></span></code></pre></div><p>样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: &lt;​auth-scheme&gt; &lt;​authorization-parameters&gt;</span></span></code></pre></div><ul><li>补充：如果要了解关于这个头部的更多细节，还可以参考 Mozilla Developer Network 关于这个头部的更多的详细介绍。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这里的 &lt;​auth-scheme&gt;，比较常见的是 Basic 和 Digest。如果是 Basic 类型，那么它的格</span></span></code></pre></div><p>式是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Basic &lt;​credentials&gt;</span></span>
<span class="line"><span>这里的 credentials，可以是 username@site.com:hashedPassword 这种形式。</span></span></code></pre></div><p>而我们在抓包里看到的是什么格式呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: UCloud</span></span>
<span class="line"><span>ucloudabcdef.yu@testtest.com144731865200013974915:gABCDEFGQSLLsdyOjIlo21fap6o=</span></span>
<span class="line"><span>       #这里是一个空行</span></span>
<span class="line"><span>这个 Authorization: UCloud 后面多了一个换行，这就已经是一个问题了。</span></span></code></pre></div><p>更严重的是，在第二行的后面，有两次回车，或者说两次 CRLF，而这个问题更加严重。说到这里，我们就需要复习一下 HTTP 报文格式的知识了。</p><h3 id="http-报文分隔" tabindex="-1">HTTP 报文分隔 <a class="header-anchor" href="#http-报文分隔" aria-label="Permalink to &quot;HTTP 报文分隔&quot;">​</a></h3><p>跟 IP、TCP 类似，HTTP 也分为头部（headers）和载荷（body 或者 payload）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/9.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/9.png" alt=""></a></p><p>既然分成了两个部分，那么显然，接收者需要知道 header 和 payload 的分界线，要不然就会导致信息解读错误，这是致命的。</p><p>在 IP 协议里，IP header 是用一个 Total Length 字段，表示了包含 IP 头部在内的整个 IP 报文的长度。那怎么区分 IP 头部和载荷呢？IP 头部还有一个字段是 Header Length，表示了头部自身的长度。这样两个 Length 值的差，就是 IP 载荷的大小了。</p><p>在 TCP 协议里，TCP header 里的 Data offset，表示了 TCP 载荷开始的位置（也是 TCP 头部截止的位置），也就相应地可以计算出 TCP 头部的长度。那么 TCP 载荷长度是怎么来的呢？我们用一个简单的减法就好了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TCP payload Length = IP Total Length - IP Header Length - TCP Header Length</span></span></code></pre></div><p>这些头部长度的关系，我用了一张示意图来概括，供你参考：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/10.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/10.png" alt=""></a></p><p>而在 HTTP 里，载荷的长度一般也是由一个 HTTP header（这里指的是某一个头部项，而不是整个 HTTP 头部），也就是 Content-length 来表示的。假设你有一次 PUT 或者 POST 请求，比如上传一个文件，那么这个文件的大小，就会被你的 HTTP 客户端程序（无论是 curl还是 Chrome 等）获取到，并设置为 Content-Length 头部的值，然后把这个 header 封装到整体的 HTTP 请求报文中去。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/11.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/11.png" alt=""></a></p><p>既然 HTTP 报文内容，分成了头部（headers）和载荷（Payload 或者 body）两部分，那么这两者的分界线在哪呢？</p><p>HTTP 规定，头部和载荷的分界线是两次 CRLF。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>A request message from a client to a server includes, within the</span></span>
<span class="line"><span>  first line of that message, the method to be applied to the resource,</span></span>
<span class="line"><span>  the identifier of the resource, and the protocol version in use.</span></span>
<span class="line"><span>       Request       = Request-Line              ; Section 5.1</span></span>
<span class="line"><span>                       *(( general-header        ; Section 4.5</span></span>
<span class="line"><span>                        | request-header         ; Section 5.3</span></span>
<span class="line"><span>                        | entity-header ) CRLF)  ; Section 7.1</span></span>
<span class="line"><span>                       CRLF</span></span>
<span class="line"><span>                       [ message-body ]          ; Section 4.3</span></span></code></pre></div><p>也就是在最后一个 header 之后，需要有两个 CRLF，这就是头部和载荷之间的分割线。之后就是载荷（message body）的开始了。</p><p>那么，前面引发 HTTP 400 的 PUT 请求，其 Authorization 后面也出现了两个 CRLF，这就会被认为是 headers 的结束，payload 的开始。但实际上，后面跟的又是剩余的 HTTP 头部项，在最后一个头部之后，又是两个 CRLF。所以这对于 Web 服务端来说就懵了：“你这说的可不是人话啊！我只能表示我不理解。”</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/12.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E7%BD%91%E7%BB%9C%E6%8E%92%E6%9F%A5%E6%A1%88%E4%BE%8B%E8%AF%BE/images/16-%25E6%259C%258D%25E5%258A%25A1%25E5%2599%25A8%25E4%25B8%25BA%25E4%25BB%2580%25E4%25B9%2588%25E5%259B%259E%25E5%25A4%258DHTTP400%25EF%25BC%259F/12.png" alt=""></a></p><h3 id="定位不合规处" tabindex="-1">定位不合规处 <a class="header-anchor" href="#定位不合规处" aria-label="Permalink to &quot;定位不合规处&quot;">​</a></h3><p>原来如此，这次的 400 Bad Request 的根因，是客户发送的 HTTP PUT 请求的格式出现了问题。它违背了 HTTP/1.1（RFC2616）的规定，在 Authorization 头部后面，错误地添加了两次回车（CRLF）。这样就导致服务端认为，后续的数据都属于 payload，也就导致服务器无法正常读取这个请求，只能用 HTTP 400 来反馈这种状况了。</p><p>既然咱们的课程叫“网络排查案例课”，那么这次案例的根因，跟网络有没有关系呢？</p><p>我觉得要看你怎么定义“网络”。</p><p>如果是传统和狭义上的网络，只包含交换机、路由器、防火墙、负载均衡等环节，那么这里并没有什么问题。没什么重传，也不丢包，更不影响应用消息本身。</p><p>如果是广义的网络，那就包含了至少以下几个领域：</p><ul><li><p>对应用层协议的理解；</p></li><li><p>对传输层和应用层两者协同的理解；</p></li><li><p>对操作系统的网络部分的理解。</p></li></ul><p>在这个案例里，我们依托于对应用层协议的理解，找到了网络行为以外的根因。这个根因虽然可能根源是开发方面的问题，但无论是开发、运维或者 SRE，在处理这种问题的时候，如果能具备比较全面的知识，从而推导出根因，那么无论是对组织效率的提升，还是个人能力的提升，是不是都更有意义呢？</p><h2 id="实验" tabindex="-1">实验 <a class="header-anchor" href="#实验" aria-label="Permalink to &quot;实验&quot;">​</a></h2><p>现在，我们也来做几个简便的小实验，模拟出 HTTP 400 Bad Request 这样的响应。</p><h3 id="实验-1-对-http-发送不合规的请求" tabindex="-1">实验 1：对 HTTP 发送不合规的请求 <a class="header-anchor" href="#实验-1-对-http-发送不合规的请求" aria-label="Permalink to &quot;实验 1：对 HTTP 发送不合规的请求&quot;">​</a></h3><p>如果我们直接用高级语言来调用 HTTP 库，可能反而不容易做到这种“非法”请求。因为这些库的设计目的之一，就是要尽量避免人工的编码错误以及提升开发效率，我们想借助它去构造非法请求，恐怕不太容易。</p><p>当然，如果你熟悉 Python 的话，可能会想到用 Scapy 库等工具来实现。但这个步骤就稍多了点。</p><p>其实，我们也可以用最简单的方法，就是直接用 telnet 命令。我们在第 2 讲里，用视频的形式介绍了如何一边用 telnet 模拟发送 HTTP 请求，一边用 tcpdump 的 -X 参数，展示抓取的报文里面的文本细节。</p><p>那么这里，我们也用类似的方法，只要手动执行下面的命令，就可以向目标站点发送一个不合规的请求：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ telnet www.baidu.com 80</span></span>
<span class="line"><span>Trying 180.101.49.12...</span></span>
<span class="line"><span>Connected to www.a.shifen.com.</span></span>
<span class="line"><span>Escape character is &#39;^]&#39;.</span></span>
<span class="line"><span>GET / HTTP/1.1</span></span>
<span class="line"><span>Authorization  #这里是一次回车</span></span>
<span class="line"><span>              #这里是又一次回车</span></span>
<span class="line"><span>HTTP/1.1 400 Bad Request</span></span>
<span class="line"><span>Connection closed by foreign host.</span></span></code></pre></div><p>也就是 telnet 目标站点的 80 端口，在提示符下输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET / HTTP/1.1</span></span></code></pre></div><p>然后回车，再输入：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization</span></span></code></pre></div><p>注意这里不要输入更多内容，直接回车两次。这时，两次回车被对端 Web 服务器收到后，它是这么解读的：</p><ul><li><p>这是一个 GET / 的 HTTP/1.1 版本的请求。</p></li><li><p>有一个 Authorization 头部，但是这个头部并没有值。</p></li><li><p>两次回车就表示这次请求发送结束。</p></li></ul><p>由于请求不合规，目标站点立刻回复了 HTTP 400 Bad Request。</p><p>而如果我们在输入 Authorization 时，后面加上“: Basic”，会收到 HTTP 500。这是因为服务端认为 Authorization: Basic 这个格式本身是正确的，只是后面缺少了真正的凭据（Credential），所以报告了 HTTP 500。</p><p>所以，两者的区别就是：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization 后面直接回车，就表示它并没有带上 &lt;​auth-scheme&gt;，所以属于不合规，</span></span></code></pre></div><ul><li>应该回复 HTTP 400。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Basic 后直接回车，它的 Authorization 头部有 &lt;​auth-scheme&gt;，但是没</span></span></code></pre></div><ul><li>有带上有效的凭据，应该回复 HTTP 500。</li></ul><h3 id="实验-2-对-https-发送不合规的请求" tabindex="-1">实验 2：对 HTTPS 发送不合规的请求 <a class="header-anchor" href="#实验-2-对-https-发送不合规的请求" aria-label="Permalink to &quot;实验 2：对 HTTPS 发送不合规的请求&quot;">​</a></h3><p>前面实验的是 HTTP 站点，我们用 telnet 发送明文请求比较直观。而要是对方站点是 HTTPS的话，如果还是用 telnet，会遇到 TLS 握手，这一关就过不去了。那么该怎么办呢？</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>其实，我们可以用 openssl 命令。执行openssl s_client -connect 站点名:443，就</span></span></code></pre></div><p>可以跟对端站点建立 TLS 握手。比如像下面这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ openssl s_client -connect www.baidu.com:443</span></span>
<span class="line"><span>CONNECTED(00000006)</span></span>
<span class="line"><span>depth=2 C = BE, O = GlobalSign nv-sa, OU = Root CA, CN = GlobalSign Root CA</span></span>
<span class="line"><span>verify return:1</span></span>
<span class="line"><span>depth=1 C = BE, O = GlobalSign nv-sa, CN = GlobalSign Organization Validation CA</span></span>
<span class="line"><span>verify return:1</span></span>
<span class="line"><span>depth=0 C = CN, ST = beijing, L = beijing, OU = service operation department, O =</span></span>
<span class="line"><span>verify return:1</span></span>
<span class="line"><span>---</span></span>
<span class="line"><span>......</span></span></code></pre></div><p>另外还有一点，我们这个时候怎么发送 HTTP 请求呢？不少人会在这里卡住。其实，openssl也是一个交互式的命令，跟 telnet 一样，直接键入 HTTP 请求就好了！</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>---</span></span>
<span class="line"><span>GET / HTTP/1.1</span></span>
<span class="line"><span>Authorization  #这里是一次回车</span></span>
<span class="line"><span>              #这里是又一次回车</span></span>
<span class="line"><span>HTTP/1.1 400 Bad Request</span></span>
<span class="line"><span>closed</span></span></code></pre></div><p>这样一来，也可以得到跟 telnet 80 一样的响应。</p><p>其实，网络协议就是这样，是一种“方言”，互相要用对方听得懂的方式对话。如果语法出现了问题，我们的自然语言就是“不明白你的意思，你说啥”。在 HTTP 这个“方言”里，就是用HTTP 400 表达了同样的意思。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>这节课，我们通过一个服务器回复 HTTP 400 的案例，学习了这种对 HTTP 返回码进行排查的方法。</p><p>使用这种方法的前提，还是需要你对 HTTP 协议本身有比较深入的掌握，然后结合对 HTTP语义的理解，分析出根因。而熟悉 HTTP 协议的方法，就是熟读 RFC2616，以及 2014 年 6月的更新 RFC（7230, 7231, 7232, 7233, 7234, 7235）。</p><p>具体的方法，我们可以借鉴这样的方式：</p><ul><li><p>我们可以把错误的报文跟成功的报文放一起，进行对比分析。这样会比较快地发现两者之间的差别，从而更快地定位到根因。</p></li><li><p>我们也可以通过 telnet 和 openssl，分别模拟复现 HTTP 和 HTTPS 的请求，重放给服务端，观察其是否也返回同样的报错。</p></li><li><p>对比协议规范和报文中抓取到的实际行为，找到不符合规范之处，很可能这就是根因。</p></li></ul><p>同时，我们也回顾了不少 HTTP 协议的知识，包括：</p><ul><li>HTTP 的各种版本的知识点：HTTP/2 和 HTTP/3 的语义跟 HTTP/1.x 是一致的，不同的是HTTP/2 和 HTTP/3 在传输效率方面，采用了更加先进的方案。</li></ul><div class="language-xml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">xml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Authorization 头部的知识点：它的格式为 Authorization: &lt;​auth-scheme&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;​authorization-parameters&gt;，如果缺少了某一部分，就可能引发服务端报 HTTP</span></span></code></pre></div><ul><li><p>400 或者 500。</p></li><li><p>HTTP 报文的知识点：两次回车（两个 CRLF）是分隔 HTTP 头部和载荷的分隔符。</p></li><li><p>HTTP 返回码的知识点：HTTP 400 Bad Request 在语义上表示的是请求不符合 HTTP 规范的情况，各种不合规的请求都可能导致服务端回复 HTTP 400。</p></li></ul><p>最后，我们通过两个小实验，学习了用简单的方式模拟 HTTP 请求的方法。如果服务端是HTTP，我们用 telnet；如果服务端是 HTTPS，就用 openssl。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>给你留两道思考题：</p><ul><li><p>在 HTTP 请求里，我们用 Content-Length 表示了 HTTP 载荷，或者说 HTTP body 的长度，那有时候无法提前计算出这种长度，HTTP 是如何表示这种“动态”的长度呢？</p></li><li><p>HTTP 请求的动词加 URL 部分，比如 GET /abc，它是属于 headers，还是属于 body，或者哪种都不属于，是独立的呢？</p></li></ul><p>你可以在留言区说说你的想法和思考，我们一起交流。另外也欢迎你把今天的内容分享给更多的朋友。</p>`,146)])])}const d=a(i,[["render",p]]);export{T as __pageData,d as default};
